
CREATE TABLE mfg_machine_hold (hold_id UUID PRIMARY KEY, machine_id UUID NOT NULL REFERENCES mfg_machine(id), restore_state VARCHAR(20) NOT NULL);
CREATE INDEX ix_machine_hold_machine ON mfg_machine_hold(machine_id);
CREATE TABLE ops_area (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL);
CREATE TABLE ops_asset (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, area_id UUID NOT NULL REFERENCES ops_area(id), name VARCHAR(160) NOT NULL, kind VARCHAR(40) NOT NULL, state VARCHAR(20) NOT NULL CHECK(state IN ('AVAILABLE','UNAVAILABLE')));
CREATE TABLE ops_technician (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, user_subject VARCHAR(160) UNIQUE NOT NULL);
CREATE TABLE ops_plan (id UUID PRIMARY KEY, machine_id UUID NOT NULL REFERENCES mfg_machine(id), interval_days INTEGER NOT NULL CHECK(interval_days>0), next_due DATE NOT NULL, instructions VARCHAR(500) NOT NULL, currency VARCHAR(3) NOT NULL);
CREATE TABLE ops_work_order (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, machine_id UUID REFERENCES mfg_machine(id), asset_id UUID REFERENCES ops_asset(id), plan_id UUID REFERENCES ops_plan(id), due_date DATE, technician_id UUID REFERENCES ops_technician(id), kind VARCHAR(20) NOT NULL, description VARCHAR(500) NOT NULL, state VARCHAR(20) NOT NULL CHECK(state IN ('OPEN','ASSIGNED','IN_PROGRESS','REVIEW','CLOSED')), repair_notes VARCHAR(1000), submitted_at TIMESTAMP WITH TIME ZONE, release_notes VARCHAR(1000), currency VARCHAR(3) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, CHECK((machine_id IS NULL AND asset_id IS NOT NULL) OR (machine_id IS NOT NULL AND asset_id IS NULL)), UNIQUE(plan_id,due_date));
CREATE TABLE ops_part_stock (product_id UUID PRIMARY KEY REFERENCES catalog_product(id), quantity NUMERIC(19,6) NOT NULL CHECK(quantity>=0));
CREATE TABLE ops_part_event (event_id UUID PRIMARY KEY, product_id UUID NOT NULL REFERENCES catalog_product(id), work_order_id UUID REFERENCES ops_work_order(id), kind VARCHAR(12) NOT NULL, quantity NUMERIC(19,6) NOT NULL CHECK(quantity>0), unit_cost NUMERIC(19,6) NOT NULL CHECK(unit_cost>=0), currency VARCHAR(3) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE ops_labor (event_id UUID PRIMARY KEY, work_order_id UUID NOT NULL REFERENCES ops_work_order(id), hours NUMERIC(12,6) NOT NULL CHECK(hours>0), hourly_rate NUMERIC(19,6) NOT NULL CHECK(hourly_rate>=0), created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE ops_service_contract (id UUID PRIMARY KEY, asset_id UUID NOT NULL REFERENCES ops_asset(id), supplier_reference VARCHAR(120) NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, amount NUMERIC(19,6) NOT NULL CHECK(amount>=0), currency VARCHAR(3) NOT NULL, CHECK(ends_on>=starts_on));
CREATE TABLE ops_asset_inspection (id UUID PRIMARY KEY, asset_id UUID NOT NULL REFERENCES ops_asset(id), passed BOOLEAN NOT NULL, notes VARCHAR(1000) NOT NULL, inspector VARCHAR(160) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE ops_yard_space (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, kind VARCHAR(12) NOT NULL CHECK(kind IN ('PARKING','DOCK')), active BOOLEAN NOT NULL);
CREATE TABLE ops_truck_visit (id UUID PRIMARY KEY, reference VARCHAR(40) UNIQUE NOT NULL, carrier VARCHAR(160) NOT NULL, driver VARCHAR(160) NOT NULL, tractor_plate VARCHAR(40) NOT NULL, trailer_plate VARCHAR(40) NOT NULL, purpose VARCHAR(20) NOT NULL, document_reference VARCHAR(120) NOT NULL, planned_start TIMESTAMP WITH TIME ZONE NOT NULL, planned_end TIMESTAMP WITH TIME ZONE NOT NULL, space_id UUID REFERENCES ops_yard_space(id), state VARCHAR(24) NOT NULL CHECK(state IN ('SCHEDULED','ARRIVED','GATE_CHECKED','WAITING','AT_DOCK','HANDLING','READY_EXIT','DEPARTED','CANCELLED','REJECTED')), documents_checked BOOLEAN NOT NULL, gate_notes VARCHAR(500), entry_at TIMESTAMP WITH TIME ZONE, exit_at TIMESTAMP WITH TIME ZONE, CHECK(planned_end>planned_start));
CREATE TABLE ops_dock_booking (visit_id UUID PRIMARY KEY REFERENCES ops_truck_visit(id), space_id UUID NOT NULL REFERENCES ops_yard_space(id), starts_at TIMESTAMP WITH TIME ZONE NOT NULL, ends_at TIMESTAMP WITH TIME ZONE NOT NULL, CHECK(ends_at>starts_at));
CREATE INDEX ix_dock_booking_interval ON ops_dock_booking(space_id,starts_at,ends_at);
CREATE TABLE ops_weight_ticket (event_id UUID PRIMARY KEY, visit_id UUID NOT NULL REFERENCES ops_truck_visit(id), kind VARCHAR(8) NOT NULL CHECK(kind IN ('TARE','GROSS')), kg NUMERIC(19,6) NOT NULL CHECK(kg>0), measured_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(visit_id,kind));
CREATE TABLE ops_visit_event (id UUID PRIMARY KEY, visit_id UUID NOT NULL REFERENCES ops_truck_visit(id), state VARCHAR(24) NOT NULL, notes VARCHAR(500) NOT NULL, actor VARCHAR(160) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE ops_access_zone (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL);
CREATE TABLE ops_visitor (id UUID PRIMARY KEY, reference VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, company VARCHAR(160) NOT NULL, host_reference VARCHAR(120) NOT NULL, badge VARCHAR(40), valid_from TIMESTAMP WITH TIME ZONE NOT NULL, valid_to TIMESTAMP WITH TIME ZONE NOT NULL, safety_briefed BOOLEAN NOT NULL, state VARCHAR(16) NOT NULL CHECK(state IN ('EXPECTED','CHECKED_IN','CHECKED_OUT','CANCELLED')), CHECK(valid_to>valid_from));
CREATE TABLE ops_visitor_zone (visitor_id UUID REFERENCES ops_visitor(id), zone_id UUID REFERENCES ops_access_zone(id), PRIMARY KEY(visitor_id,zone_id));
CREATE TABLE ops_badge (code VARCHAR(40) PRIMARY KEY, active BOOLEAN NOT NULL);
CREATE TABLE ops_access_event (event_id UUID PRIMARY KEY, visitor_id UUID NOT NULL REFERENCES ops_visitor(id), zone_id UUID NOT NULL REFERENCES ops_access_zone(id), direction VARCHAR(8) NOT NULL CHECK(direction IN ('ENTER','EXIT')), actor VARCHAR(160) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE ops_presence (visitor_id UUID PRIMARY KEY REFERENCES ops_visitor(id), zone_id UUID NOT NULL REFERENCES ops_access_zone(id));
CREATE TABLE ops_incident (id UUID PRIMARY KEY, zone_id UUID REFERENCES ops_access_zone(id), severity VARCHAR(12) NOT NULL, description VARCHAR(1000) NOT NULL, state VARCHAR(12) NOT NULL CHECK(state IN ('OPEN','RESOLVED')), resolution VARCHAR(1000), created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE ops_camera (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, zone_id UUID NOT NULL REFERENCES ops_access_zone(id), name VARCHAR(160) NOT NULL, vms_reference VARCHAR(160) NOT NULL, state VARCHAR(20) NOT NULL CHECK(state IN ('ONLINE','OFFLINE','MAINTENANCE')));
CREATE TABLE ops_audit (id UUID PRIMARY KEY, entity_id UUID NOT NULL, action VARCHAR(80) NOT NULL, details TEXT NOT NULL, actor VARCHAR(160) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX ix_work_order_machine ON ops_work_order(machine_id,state);
CREATE INDEX ix_truck_space ON ops_truck_visit(space_id,state);
CREATE INDEX ix_visitors_badge ON ops_visitor(badge,state);

CREATE TABLE ops_yard_lock (id INTEGER PRIMARY KEY); INSERT INTO ops_yard_lock VALUES (1);
CREATE TABLE ops_access_lock (id INTEGER PRIMARY KEY); INSERT INTO ops_access_lock VALUES (1);
